#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
  [[ $EUID -ne 0 ]] || { printf 'Do not run this launcher as root.\n' >&2; return 1; }
  if [[ ${1:-} != wizard ]]; then
    exec "$XBOX_FIRMWARE_BACKEND" "$@"
  fi
  [[ $# -le 2 && -t 0 && -t 1 ]] || { printf 'Usage: xbox-firmware-vm wizard [private-state-directory], in a terminal\n' >&2; return 1; }
  base=${2:-${XDG_DATA_HOME:-$HOME/.local/share}/xbox-firmware-maintenance}
  base=$("$XBOX_FIRMWARE_BACKEND" --state "$base" init)
  exec 9>"$base/wizard.lock"
  flock -n 9 || { printf 'Another wizard is using this directory.\n' >&2; return 1; }
  ENV_FILE="$base/wizard.env"
  [[ ! -L $ENV_FILE ]] || { printf 'Refusing symlink settings.\n' >&2; return 1; }
  export ENV_FILE
  TOTAL_STAGES=5
  usb_armed=0
  trap 'wizard_interrupted "$base" "$usb_armed"' EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM HUP
  banner "Official Xbox firmware maintenance VM"
  stage "Official Windows ISO and integrity"
  say "Host infrastructure is automated; Windows setup/accounts and the official updater are manual."
  say "No passwords, license keys, or accounts are captured. No licensing/OOBE bypasses."
  "$XBOX_FIRMWARE_BACKEND" --state "$base" status
  if ! confirm "Reuse an already provisioned VM in THIS state directory (skip ISO download)"; then
    say "Automatically select current consumer Windows 11, English (US), x64 on Microsoft's page."
    say "An isolated browser resolves the link and matching official SHA256; no copy/paste needed."
    note "Restrictions/schema changes stop safely. CLI --language or --iso + --sha256 are optional overrides."
    ask VM_NAME "New VM name (suggested: xbox-firmware-maintenance):"
    [[ -n $VM_NAME ]] || VM_NAME=xbox-firmware-maintenance
    write_env VM_NAME "$VM_NAME"
    confirm "Create/reuse only this owned VM; 4 vCPU, 8 GiB RAM, sparse 80 GiB disk defaults" || return 1
    "$XBOX_FIRMWARE_BACKEND" --state "$base" provision --name "$VM_NAME"
  fi
  stage "Windows setup and official Accessories"
  "$XBOX_FIRMWARE_BACKEND" --state "$base" open
  step "In the viewer, press a key to boot ISO on FIRST install. Install Windows to the VM's empty SATA disk only."
  step "After first restart do NOT press a key to boot ISO again. Complete supported setup, licensing, sign-in and Windows Update manually."
  step "In WINDOWS Win+R, open: ms-windows-store://pdp/?ProductId=9NBLGGH30XJ3"
  step "New VMs include read-only XBOX_TOOLS disc: inspect/run guest-tools.cmd to open that listing and show the awake command."
  step "Install/open official Xbox Accessories (Microsoft Corporation). Do not click Update yet."
  pause "Continue only when Windows and Accessories are ready; no firmware operation running."
  stage "Dedicated USB socket: cold xpad-free handoff"
  "$XBOX_FIRMWARE_BACKEND" controllers
  step "Connect target controller directly with a good data cable; remove OTHER xpad controllers."
  step "Select exact serial/direct port below; rerun 'xbox-firmware-vm controllers' if needed."
  ask USB_PORT "USB direct port (bus-port, no downstream hub):"
  ask USB_SERIAL "Exact controller serial shown above:"
  write_env USB_PORT "$USB_PORT"
  write_env USB_SERIAL "$USB_SERIAL"
  warn "Reserve this SOCKET exclusively for this controller, including unknown bootloader identities. Never plug anything else there."
  warn "Normal-mode serial is enforced; unknown modes cannot be authenticated by serial. xpad is temporarily inhibited globally."
  confirm "Dedicated controller-only socket; allow bounded terminal sudo (other xpad devices/users cause refusal)" || return 1
  usb_armed=1
  "$XBOX_FIRMWARE_BACKEND" --state "$base" usb-start --port "$USB_PORT" --serial "$USB_SERIAL"
  pause "Wait a moment, then inspect guard readiness below."
  "$XBOX_FIRMWARE_BACKEND" --state "$base" usb-status
  step "UNPLUG controller completely (including batteries); wait ten seconds. Leave it disconnected."
  pause "Press Enter while controller is still UNPLUGGED."
  "$XBOX_FIRMWARE_BACKEND" --state "$base" usb-attach
  step "Reconnect ONLY this controller to the SAME socket; wait for Accessories recognition."
  pause "When recognized, continue (do not Update)."
  stage "Reconnect proof and sleep protection"
  step "Before any update, unplug ten seconds and reconnect to the SAME socket ONCE MORE."
  step "Accessories must recognize it without reattach, permissions commands, or host xpad initialization."
  pause "Continue only after that SECOND successful physical reconnect."
  "$XBOX_FIRMWARE_BACKEND" --state "$base" usb-status
  note "Require phase=running, ready=true, generation >=3; your full physical PCI path and serial."
  step "Record full BEFORE firmware version and offered update. Keep host on AC; independent guard blocks host sleep/idle."
  step "Reviewed guest sleep helper: $XBOX_GUEST_AWAKE"
  step "On new VMs, inspect guest-awake.ps1 on the XBOX_TOOLS CD; run in Windows PowerShell with your consent (no file transfer)."
  note "Previously created VMs are never redefined; if no tools disc exists, transfer the reviewed helper yourself."
  step "Check 'Guest awake'; keep that SAME window/thread running until completion. No permanent settings are changed."
  warn "Without guest AND host sleep protection, stop. Do not bypass execution policy/security. Do not manually suspend/reboot."
  confirm "Reconnect proof, exact controller, guest awake helper, and stable power verified" || return 1
  stage "Guarded official update, verification and cleanup"
  confirm "Arm persistent FLASH-ACTIVE protection BEFORE clicking official update" || return 1
  "$XBOX_FIRMWARE_BACKEND" --state "$base" flash-active
  notify-send "Xbox maintenance protected" "Do not interrupt power, USB, VM or guest awake loop." || true
  step "Now use Xbox Accessories' official Update flow. Never reset/detach/reboot while working."
  step "Wait for explicit Updated/success; reopen details and verify full AFTER version and no update available."
  warn "Error, ambiguity or interruption: leave protection active. Do not guess success, force cleanup or retry blindly."
  confirm "Official completion AND reread firmware version verified (otherwise No; use recovery docs)" || return 1
  "$XBOX_FIRMWARE_BACKEND" --state "$base" flash-complete
  "$XBOX_FIRMWARE_BACKEND" --state "$base" usb-stop
  usb_armed=0
  "$XBOX_FIRMWARE_BACKEND" --state "$base" usb-status
  step "Confirm phase=stopped; now end guest awake PowerShell with Ctrl+C. VM/disk remain reusable; shut down Windows normally if desired."
  notify-send "Xbox maintenance finished" "Verify stopped guard status. VM retained; no future USB capture armed." || true
  trap - EXIT INT TERM HUP
  finish
}

wizard_interrupted() {
  local base=$1 armed=$2
  trap - EXIT
  if [[ $armed == 1 ]]; then
    printf '\nInterrupted: active flash is NEVER cleaned up automatically. Inspect recovery documentation.\n' >&2
    # Independent failure cleanup; refuses ALL detach/cleanup while flash-active.
    "$XBOX_FIRMWARE_BACKEND" --state "$base" usb-stop || true
    printf 'Resume with: xbox-firmware-vm --state %q usb-status\n' "$base" >&2
  fi
}
run_wizard "$@"; exit
